typedef float rational_t;
typedef float time_value_t;

extern "C" float sqrtf(float);
__asm__(".equ sqrtf, 0x003C7058");

struct vector3d
{
  float x, y, z;
  vector3d() {}
  vector3d(float _x, float _y, float _z) : x(_x), y(_y), z(_z) {}
  vector3d operator-(const vector3d& b) const { return vector3d(x-b.x, y-b.y, z-b.z); }
  vector3d operator+(const vector3d& b) const { return vector3d(x+b.x, y+b.y, z+b.z); }
  vector3d operator*(float f) const { return vector3d(x*f, y*f, z*f); }
  vector3d& operator*=(float f) { x*=f; y*=f; z*=f; return *this; }
};

inline float fast_length2(float x, float y, float z) { return x*x + y*y + z*z; }
inline float __fsqrt(float x) { return sqrtf(x); }
inline float fast_recip_length(float x, float y, float z) { return 1.0f / sqrtf(x*x + y*y + z*z); }

extern const vector3d XVEC;
__asm__(".equ XVEC, 0x005787C0");

class particle_generator {};

class particle
{
  vector3d my_pos;
  vector3d my_velocity;
  vector3d rot_axis;
  rational_t scale;
  rational_t rotation;
  rational_t rotation_speed;
  time_value_t life_remaining;
  time_value_t total_life;
  friend class particle_force;
};

class particle_force
{
public:
  enum force_flavor_t { CONSTANT, RESISTANCE, TOWARDS_POINT };
  vector3d get_new_v(const particle&, particle_generator&, time_value_t);
  force_flavor_t flavor;
  vector3d multipurpose;
  vector3d utility;
  rational_t delta_speed;
  rational_t terminal_speed;
  rational_t recip_terminal_speed;
};

vector3d particle_force::get_new_v( const particle& _particle, particle_generator& pg, time_value_t delta_t )
{
  vector3d result;
  if (flavor==RESISTANCE)
  {
    rational_t norm_vel = fast_length2(_particle.my_velocity.x, _particle.my_velocity.y, _particle.my_velocity.z );
    if( norm_vel > terminal_speed*terminal_speed)
    {
      norm_vel = __fsqrt(norm_vel);
      rational_t mul = -delta_speed * (norm_vel-terminal_speed) / norm_vel;
      mul *= delta_t;
      result = _particle.my_velocity * (mul + 1.0f);
    }
    else
      result = _particle.my_velocity;
  }
  else
  {
    if (flavor==CONSTANT)
    {
      result = _particle.my_velocity + multipurpose * delta_t;
    }
    else
    {
      vector3d orientation = utility - _particle.my_pos;
      rational_t recip_n = fast_recip_length(orientation.x, orientation.y, orientation.z);
      if (recip_n>100)
      {
        orientation = XVEC;
        recip_n = 1;
      }
      orientation *= delta_speed * recip_n;
      result = _particle.my_velocity + orientation * delta_t;
    }
    float recip_norm_result = fast_recip_length(result.x, result.y, result.z);
    if (recip_norm_result < recip_terminal_speed)
    {
      result = result * (terminal_speed * recip_norm_result);
    }
  }
  return result;
}
